pous.declaration:
FUNCTION_BLOCK MaterialMix
VAR_INPUT
    estop : BOOL;
    opeMode : BOOL;
    valveAStart : BOOL;
    valveBStart : BOOL;
    valveCStart : BOOL;
    valveDStart : BOOL;
    mixMotorStart : BOOL;
    autoStart : BOOL;
    processMode : BOOL;
    levelSensor : INT;
    mixMotorComplete : BOOL;
END_VAR
VAR_OUTPUT
    valveARun : BOOL;
    valveBRun : BOOL;
    valveCRun : BOOL;
    valveDRun : BOOL;
    mixMotorRun : BOOL;
END_VAR
VAR
    va : BOOL;
    vb : BOOL;
    vc : BOOL;
    vd : BOOL;
    mm : BOOL;
    aPrev : BOOL;
    bPrev : BOOL;
    cPrev : BOOL;
    dPrev : BOOL;
    mPrev : BOOL;
    autoStage : INT := 0;
    autoStartPrev : BOOL;
END_VAR

pous.implementation:
IF NOT estop THEN
    va := FALSE;
    vb := FALSE;
    vc := FALSE;
    vd := FALSE;
    mm := FALSE;
    autoStage := 0;
ELSIF NOT opeMode THEN
    IF valveAStart AND NOT aPrev THEN
        va := NOT va;
    END_IF
    IF valveBStart AND NOT bPrev THEN
        vb := NOT vb;
    END_IF
    IF valveCStart AND NOT cPrev THEN
        vc := NOT vc;
    END_IF
    IF valveDStart AND NOT dPrev THEN
        vd := NOT vd;
    END_IF
    IF mixMotorStart AND NOT mPrev THEN
        mm := NOT mm;
    END_IF
    autoStage := 0;
ELSE
    va := FALSE;
    vb := FALSE;
    vc := FALSE;
    vd := FALSE;
    mm := FALSE;
    CASE autoStage OF
    0:
        IF autoStart AND NOT autoStartPrev THEN
            autoStage := 1;
        END_IF
    1:
        va := TRUE;
        IF levelSensor >= 50 THEN
            autoStage := 2;
        END_IF
    2:
        vb := TRUE;
        IF levelSensor >= 80 THEN
            IF processMode THEN
                autoStage := 4;
            ELSE
                autoStage := 3;
            END_IF
        END_IF
    3:
        mm := TRUE;
        IF mixMotorComplete THEN
            autoStage := 5;
        END_IF
    4:
        vc := TRUE;
        IF levelSensor >= 100 THEN
            autoStage := 3;
        END_IF
    5:
        vd := TRUE;
    END_CASE
END_IF
valveARun := va;
valveBRun := vb;
valveCRun := vc;
valveDRun := vd;
mixMotorRun := mm;
aPrev := valveAStart;
bPrev := valveBStart;
cPrev := valveCStart;
dPrev := valveDStart;
mPrev := mixMotorStart;
autoStartPrev := autoStart;
